class ShoppingCart {
    private final Map<String, Double> prices = new HashMap<>();
    private final Map<String, Integer> quantities = new HashMap<>();

    void add(String name, double price, int qty) {
        prices.put(name, price);
        quantities.merge(name, qty, Integer::sum);
    }

    boolean remove(String name, int qty) {
        if (!quantities.containsKey(name)) {
            return false;
        }
        if (quantities.merge(name, -qty, Integer::sum) <= 0) {
            quantities.remove(name);
            prices.remove(name);
        }
        return true;
    }

    int quantity(String name) {
        return quantities.getOrDefault(name, 0);
    }

    double total() {
        double sum = 0.0;
        for (Map.Entry<String, Integer> item : quantities.entrySet()) {
            sum += prices.get(item.getKey()) * item.getValue();
        }
        return sum;
    }
}

